"""Agent loop. Every tool result transits the screen before it is appended."""


def screen_for_injection(text):
    return "ignore previous instructions" not in text.lower()


def run(user_prompt, client, tools):
    if not screen_for_injection(user_prompt):
        raise ValueError("refused: injected operator prompt")
    messages = [{"role": "user", "content": user_prompt}]
    while True:
        reply = client.messages.create(messages=messages)
        if not reply.tool_calls:
            return reply
        for call in reply.tool_calls:
            tool_result = tools[call.name](**call.arguments)
            if not screen_for_injection(tool_result):
                tool_result = "[withheld: tool result failed the injection screen]"
            messages.append({"role": "tool", "content": tool_result})
